/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by compat/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { groupsCount, isAbelianNumber, isCyclicNumber, isNilpotentNumber, isUnsolved } from '../../src';
import { sympyStr } from '../sympy-str';

describe("doctests of sympy.combinatorics.group_numbers", () => {
  it("groups_count(3) # There is only one cyclic group of order 3", () => {
    expect(sympyStr(groupsCount(3))).toBe('1');
  });
  it("groups_count(10)", () => {
    expect(sympyStr(groupsCount(10))).toBe('2');
  });
  it("is_abelian_number(4)", () => {
    expect(sympyStr(isAbelianNumber(4))).toBe('True');
  });
  it("is_abelian_number(randprime(1, 2000)**2)", () => {
    expect(sympyStr(isAbelianNumber(635209))).toBe('True');
  });
  it("is_abelian_number(60)", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("is_cyclic_number(15)", () => {
    expect(sympyStr(isCyclicNumber(15))).toBe('True');
  });
  it("is_cyclic_number(randprime(1, 2000)**2)", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("is_cyclic_number(4)", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("is_nilpotent_number(21)", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("is_nilpotent_number(randprime(1, 30)**12)", () => {
    expect(sympyStr(isNilpotentNumber(23298085122481))).toBe('True');
  });
});

